import 'dart:convert';
import 'dart:io';

void main(List<String> args) {
  final source = File(
    'supabase/functions/ai-album-draft/composition-contract.json',
  );
  final body =
      '''// Generated by tool/generate_ai_composition.dart. Do not edit.
const aiTemplateCompositionContract = ${const JsonEncoder.withIndent('  ').convert(jsonDecode(source.readAsStringSync()))};
''';
  final target = File(
    'lib/features/album/ai_album/domain/ai_template_composition.g.dart',
  );
  if (args.contains('--check')) {
    if (!target.existsSync() || target.readAsStringSync() != body) {
      stderr.writeln(
        'AI composition contract is stale. Run dart tool/generate_ai_composition.dart',
      );
      exitCode = 1;
    }
  } else {
    target.writeAsStringSync(body);
  }
}
